<script setup lang="ts">
const props = defineProps<{ groupId: string }>(); const emit = defineEmits(['created','cancel'])
const form = reactive({ title: '', description: '', program: '', type: 'Project', budget: 0, recurring: '', facilitator: '', evidence: '', timeline: '', meeting: '', password: '' }); const error = ref(''); const busy = ref(false)
const days = computed(() => form.type === 'Policy change' || form.budget > 5000 ? 28 : form.budget > 1000 ? 14 : 7)
async function submit() { busy.value = true; error.value = ''; try { const p = await $fetch(`/api/groups/${props.groupId}/proposals`, {method:'POST', body: form}); emit('created',p) } catch(e:any) { error.value = e.data?.statusMessage || 'Could not create proposal.' } finally { busy.value = false } }
</script>
<template><section class="panel"><div class="section-head"><h2>New proposal</h2><button class="subtle" @click="emit('cancel')">Cancel</button></div><form @submit.prevent="submit"><label>Proposal title<input v-model="form.title" required maxlength="160" placeholder="What should we decide?"></label><label>Description<textarea v-model="form.description" required maxlength="10000" rows="5" placeholder="Explain the idea, its purpose, and what agreement would mean." /></label><div class="form-grid"><label>Proposal type<select v-model="form.type"><option v-for="t in ['Project','Event','Purchase','Policy change','Other']" :key="t">{{ t }}</option></select></label><label>Setup budget (USD)<input v-model.number="form.budget" type="number" required min="0" max="1000000000000" step="0.01"></label><label>Program / impact area<input v-model="form.program" maxlength="150" placeholder="e.g. Community care"></label><label>Recurring costs<input v-model="form.recurring" maxlength="200" placeholder="e.g. $20 monthly, or none"></label><label>Proposer / facilitator<input v-model="form.facilitator" required maxlength="100"></label><label>Meeting reference <small>optional</small><input v-model="form.meeting" maxlength="200" placeholder="e.g. November house meeting"></label></div><label>Implementation timeline<textarea v-model="form.timeline" rows="2" maxlength="2000" /></label><label>Evidence of utility / supporting resources<textarea v-model="form.evidence" rows="2" maxlength="3000" /></label><label>Decision password <small>optional</small><input v-model="form.password" type="password" autocomplete="new-password" minlength="8" maxlength="200"></label><div class="notice">Review period: {{ days }} days from publication. Policy changes use a 28-day review period.</div><p v-if="error" class="error" role="alert">{{ error }}</p><button class="button" :disabled="busy">{{ busy ? 'Publishing…' : 'Publish proposal' }}</button></form></section></template>
